r.append(R(3882,"फूलगोभी स्टेक्स","फूलगोभी ने दिखा दिया है कि इसका उपयोग पहले सोची गई बातों से कहीं अधिक तरीकों से हो सकता है। फूलगोभी स्टेक्स सब्जियों को मुख्य व्यंजन के रूप में पेश करने का एक अनोखा तरीका है। वर्जीनिया की रीनल आहार विशेषज्ञ जैकी ने फूलगोभी स्टेक की एक सरल रेसिपी तैयार की है जो आपको फूलगोभी को बिल्कुल नए नज़रिए से देखने पर मजबूर कर देगी। आनंद लें!","4","1 स्टेक",
["1 मध्यम फूलगोभी","3 बड़े चम्मच जैतून का तेल","1/4 छोटा चम्मच लहसुन पाउडर","1/4 छोटा चम्मच प्याज़ पाउडर","1/8 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च"],
["ओवन को 400˚F पर पहले से गरम करें। रोस्टिंग पैन पर बेकिंग पेपर (पार्चमेंट पेपर) बिछाएँ।","फूलगोभी के पत्ते हटाएँ और डंठल का निचला हिस्सा काट दें। फूलगोभी को बीच से आधा काटें। हर आधे हिस्से को 1” से 3/4” मोटे स्लाइस में काटें, बीच का डंठल लगा रहने दें। फूलगोभी के छोटे सिरे काटकर दूसरी रेसिपी के लिए रख लें। कुल 4 फूलगोभी स्टेक बनने चाहिए।","जैतून का तेल, लहसुन पाउडर, प्याज़ पाउडर, नमक और काली मिर्च मिलाएँ।","फूलगोभी को पार्चमेंट पेपर बिछी बेकिंग शीट पर रखें। जैतून के तेल के आधे मिश्रण को ब्रश से स्टेक्स पर लगाएँ। पहले से गरम ओवन में 20 मिनट रखें। ओवन से निकालें और स्टेक्स को पलट दें। स्टेक्स पर बचा हुआ जैतून का तेल लगाएँ और किनारों के सुनहरे भूरे होने तक लगभग 20 मिनट और भूनें।"],
["बची हुई फूलगोभी को ऑमलेट में इस्तेमाल किया जा सकता है, छोटे टुकड़ों में काटकर चावल के विकल्प के रूप में उबाला जा सकता है, या खट्टी क्रीम और Mrs. Dash® से बने डिप के साथ कच्ची खाई जा सकती है।"],
["2 सब्जी, मध्यम पोटैशियम","2 वसा"]))
r.append(R(3884,"वॉटरमेलन समर कूलर","वॉटरमेलन समर कूलर की किडनी-अनुकूल रेसिपी से ठंडक पाएँ।","2","3/4 कप (6 औंस)",
["1 कप कुचली हुई बर्फ़","1 कप बिना बीज वाले तरबूज़ के टुकड़े","2 छोटे चम्मच नींबू (लाइम) का रस","1 बड़ा चम्मच चीनी","सजावट के लिए तरबूज़ की 2 छोटी फाँकें"],
["सजावट की फाँकों को छोड़कर सारी सामग्री ब्लेंडर में डालें और 30 सेकंड तक ब्लेंड करें।","2 छोटे गिलासों में डालें, फाँकों से सजाएँ और आनंद लें!"],
["तरबूज़ों की मिठास अलग-अलग होती है। ज़रूरत हो तो और स्वीटनर डालकर समायोजित करें।","तरल पदार्थ सीमित करने वाले आहार के लिए, वॉटरमेलन समर कूलर की एक सर्विंग अभी लें और एक सर्विंग बाद के लिए फ्रीज़ कर दें। परोसने से 10 से 15 मिनट पहले फ्रीज़र से निकाल लें।","अगर चीनी की जगह चीनी का विकल्प इस्तेमाल किया जाए, तो 6 औंस की सर्विंग में कार्बोहाइड्रेट घटकर 6 ग्राम और कैलोरी 26 रह जाती है।"],
["1 फल, कम पोटैशियम"]))
r.append(R(3886,"क्रीमी बेक्ड फ़िश","एरिज़ोना की DaVita रीनल आहार विशेषज्ञ बारबरा क्रीमी बेक्ड फ़िश की अपनी शानदार किडनी-अनुकूल रेसिपी साझा करती हैं। कम वसा वाली हैडॉक मछली प्रोटीन का उत्कृष्ट स्रोत है, और बारबरा की रेसिपी में इसे पूरी तरह स्वादिष्ट बनाने के लिए एक मलाईदार सॉस शामिल है।","4","3 औंस मछली और सॉस",
["1 पाउंड हैडॉक मछली","1/2 कप मैदा (ऑल-पर्पज़ व्हाइट फ़्लोर)","2 बड़े चम्मच बिना नमक का मक्खन","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","1 कप सामान्य नॉन-डेयरी क्रीमर","1 कप वसा-रहित नॉन-डेयरी क्रीमर","1/4 कप पानी"],
["ओवन को 350° F पर पहले से गरम करें।","8″ x 8″ के काँच के बेकिंग पैन पर वनस्पति तेल का स्प्रे करें। पैन की तली पर मैदे की हल्की परत (1/2 कप में से 2-3 बड़े चम्मच) बुरकें।","हैडॉक को धोएँ और हर टुकड़े को पैन में सजाकर रखें।","मछली पर नमक, काली मिर्च और बचा हुआ मैदा बुरकें। इसे बराबर फैलाएँ।","ऊपर से सामान्य वसा वाला नॉन-डेयरी क्रीमर, वसा-रहित नॉन-डेयरी क्रीमर और पानी डालें।","मक्खन को टुकड़ों में काटें और मिश्रण के ऊपर जगह-जगह रखें।","लगभग 30 से 45 मिनट या हल्का सुनहरा भूरा होने तक बेक करें।","मछली को प्लेट में निकालें। बेकिंग डिश से क्रीम सॉस चम्मच से निकालकर परोसने से पहले मछली पर डालें।"],
["हैडॉक स्टेक या फ़िले खरीदें। अगर जमी हों तो पिघला लें। फ़िले या स्टेक की मोटाई के अनुसार पकाने का समय अलग हो सकता है। 30 मिनट बाद जाँच करें।","अगर मछली पकने पर सॉस गाढ़ा न हुआ हो, तो मछली को पैन से निकालें, सॉस को चलाएँ और 5-10 मिनट के लिए वापस ओवन में रखें।","अगर आप अधिक या कम प्रोटीन वाला आहार ले रहे हैं, तो अपनी भोजन योजना के अनुसार मछली की मात्रा समायोजित करें।","चाहें तो नमक न डालें। इससे प्रति सर्विंग सोडियम घटकर 122 मिग्रा रह जाता है।"],
["3 मांस","1 स्टार्च","1 नॉन-डेयरी","1 उच्च कैलोरी"]))
r.append(R(3888,"पोलो ग्विसाडो","पोलो ग्विसाडो सब्जियों, मसालों और जड़ी-बूटियों वाला पुएर्तो रिको का चिकन स्ट्यू है, जो ज़्यादा नमक के बिना भरपूर स्वाद देता है।","4","2 कप",
["1 मध्यम आलू","1 पाउंड चिकन जाँघ, बिना हड्डी और बिना त्वचा के","2 छोटे चम्मच DaVita की घर पर बनी अडोबो सीज़निंग रेसिपी, बिना नमक के","2 बड़े चम्मच जैतून का तेल","1 मध्यम पीला प्याज़","3 लहसुन की कलियाँ","8 औंस बिना नमक मिला टमाटर सॉस","1 हरी शिमला मिर्च, बड़े टुकड़ों में कटी हुई","1 बड़ी गाजर","1-1/2 छोटे चम्मच घर पर बनी साज़ोन सीज़निंग (उपयोगी सुझाव देखें)","2 तेज पत्ते","2 छोटे चम्मच सूखा ओरेगैनो","1/4 कप मैनज़ानिलो जैतून (हरे जैतून)","3 कप बिना नमक का चिकन शोरबा (ब्रॉथ)"],
["आलू छीलें और बड़े टुकड़ों में काटें। आलू को बड़े बर्तन में पानी में नरम होने तक उबालें। पानी निथारकर अलग रख दें। चिकन की जाँघों को पेपर टॉवल से अच्छी तरह सुखा लें। दो-दो इंच के टुकड़ों में काटें और अडोबो से मसाला लगाएँ।","एक बर्तन को मध्यम-तेज़ आँच पर रखें और तेल डालें। चिकन को एक परत में डालें और भूरा करें, एक बार पलटें।","भूरा हो जाने पर चिकन को बर्तन से निकालकर अलग रख दें। प्याज़ को बड़े टुकड़ों में काटें और लहसुन को बारीक काटें। प्याज़ और लहसुन डालें और धीमी आँच पर 2 मिनट पकाएँ।","हरी शिमला मिर्च को बड़े टुकड़ों में काटें। टमाटर सॉस और शिमला मिर्च डालें और उबाल आने दें।","गाजर को 1/4-इंच के गोल टुकड़ों में काटें। साज़ोन, तेज पत्ते, ओरेगैनो, जैतून, गाजर और चिकन शोरबा डालें। उबाल आने दें।","चिकन को आलू के साथ वापस बर्तन में डालें। आँच कम करें और 45 मिनट धीमी आँच पर पकने दें।","आँच से उतारें और आनंद लें!"],
["इस रेसिपी में पोटैशियम अधिक है, लेकिन यह एक-डिश भोजन है, इसलिए पोटैशियम की यह मात्रा स्वीकार्य होगी। अगर आप कम पोटैशियम वाला आहार ले रहे हैं, तो टमाटर सॉस न डालें।","घर पर साज़ोन बनाने के लिए लहसुन पाउडर, पिसा जीरा, पिसा धनिया, पिसा अन्नाटो (या हल्दी) और पिसा ओरेगैनो बराबर मात्रा में लें। इस रेसिपी के लिए हर एक 1/4 छोटा चम्मच होगा। अन्य रेसिपी में उपयोग के लिए यह मिश्रण हाथ में रखें। दुकान से खरीदे साज़ोन में सोडियम अधिक होता है।","अन्य रेसिपी के लिए DaVita की अडोबो सीज़निंग का एक बैच भी तैयार रखें। इस रेसिपी की सामग्री में पहले से नमक शामिल है, इसलिए इस रेसिपी के लिए अडोबो सीज़निंग बनाते समय नमक न डालें।","आलू उबालने से पोटैशियम की मात्रा 50-75% कम हो जाती है। पोटैशियम को थोड़ा और कम करने के लिए आप उन्हें दो बार भी उबाल सकते हैं।"],
["3 मांस/प्रोटीन","1/2 स्टार्च","2 सब्जी, उच्च पोटैशियम"]))
r.append(R(3889,"ब्लूबेरी ब्लास्ट स्मूदी","टेक्सास की हेज़ल कभी ग्लासगो, स्कॉटलैंड की हेज़ल हुआ करती थीं, और उन्होंने अपने डायलिसिस मरीज़ों के लिए ब्लूबेरी ब्लास्ट स्मूदी नाम की एक शानदार रेसिपी खोजी है। एंटीऑक्सीडेंट से भरपूर और प्रोटीन पाउडर के बढ़ावे वाली इस स्वादिष्ट स्मूदी में इतनी अच्छी चीज़ें हैं कि आप अच्छे पोषण का धमाका महसूस करेंगे।","4","1 कप",
["1 कप जमी हुई ब्लूबेरी","8 पैकेट Splenda®","6 बड़े चम्मच प्रोटीन पाउडर","8 बर्फ़ के क्यूब","14 औंस सेब का जूस (बिना अतिरिक्त चीनी का)"],
["सारी सामग्री ब्लेंडर में डालें और चिकना होने तक ब्लेंड करें।"],
["प्रोटीन की मात्रा उपयोग किए गए प्रोटीन पाउडर के ब्रांड और प्रति बड़े चम्मच प्रोटीन की मात्रा के अनुसार अलग-अलग होगी। अधिक या कम प्रोटीन पाने के लिए आप प्रोटीन पाउडर की मात्रा समायोजित कर सकते हैं।"],
["1 मांस","1 फल, कम पोटैशियम"]))
r.append(R(3894,"टैंगी कोलस्लॉ","नेवादा की DaVita रीनल आहार विशेषज्ञ एलेन अपने होंठ सिकोड़ देने वाले नेवादाज़ बेस्ट टैंगी कोलस्लॉ की रेसिपी पेश करती हैं। यह डायलिसिस-अनुकूल रेसिपी किसी भी भोजन को और रोमांचक बना देती है।","12","3/4 कप",
["6 कप हरी पत्तागोभी","4 कप लाल पत्तागोभी","1/4 कप मीठा प्याज़","1/2 कप 1% कम वसा वाला दूध","1/2 कप खट्टी क्रीम (सावर क्रीम)","1/2 छोटा चम्मच अजवायन के बीज (सेलेरी सीड)","1/2 छोटा चम्मच Tabasco® तीखा मिर्च सॉस","3 बड़े चम्मच सफ़ेद सिरका","1 छोटी लहसुन की कली"],
["पत्तागोभी को बारीक काटें और एक बड़े कटोरे में मिलाएँ। प्याज़ को बारीक काटकर पत्तागोभी में डालें; अलग रख दें।","दूध, खट्टी क्रीम, अजवायन के बीज, Tabasco® सॉस, सिरका और बारीक कटा लहसुन मिलाएँ।","ड्रेसिंग को पत्तागोभी के मिश्रण पर डालें।","2 घंटे फ्रिज में रखें, फिर परोसें और आनंद लें।"],
["मीठे प्याज़ की किस्मों में माउई, विडालिया और वाला वाला प्याज़ शामिल हैं।","इसे साइड डिश के रूप में या बीफ़ या चिकन सैंडविच के ऊपर टॉपिंग के रूप में परोसें।"],
["1-1/2 सब्जी, मध्यम पोटैशियम","1/2 वसा"]))
r.append(R(3897,"पकोड़ा","हरी मिर्च, प्याज़ और करी पत्ते पकोड़ा की किडनी-अनुकूल रेसिपी का हिस्सा हैं।","6","4 पकोड़े",
["1 मध्यम प्याज़","3 हरी मिर्च","2 छोटे चम्मच करी पत्ते","1/2 छोटा चम्मच नमक","1/4 छोटा चम्मच बेकिंग सोडा","1 कप बेसन","1 कप चावल का आटा","1 छोटा चम्मच ट्रांस-फ़ैट रहित मार्जरीन","1 बड़ा चम्मच पानी","तलने के लिए 1 कप तेल"],
["प्याज़, हरी मिर्च और करी पत्ते काटें। नमक और बेकिंग सोडा डालकर अच्छी तरह मिलाएँ।","बेसन, चावल का आटा और पिघला हुआ मार्जरीन मिलाएँ।","सारी सामग्री (तेल को छोड़कर) मिलाएँ और ज़रूरत के अनुसार थोड़ा-थोड़ा पानी डालकर ढीले आटे जैसी गाढ़ाई तक मिलाएँ। (आपको 2 बड़े चम्मच तक पानी लग सकता है। ज़रूरत के अनुसार समायोजित करें।)","तेल गरम करें। आटे की थोड़ी-थोड़ी मात्रा तेल में डालें। कुरकुरा और भूरा होने तक तलें।"],
["बेसन को चने का आटा भी कहा जाता है।","कम सोडियम वाले नाश्ते के लिए नमक घटाकर 1/4 छोटा चम्मच कर दें या बिल्कुल न डालें।"],
["2 स्टार्च","2 वसा"]))
r.append(R(3900,"कैरेट केक विद क्रीम चीज़ आइसिंग","जॉर्जिया की DaVita रीनल आहार विशेषज्ञ लूसी को अपने कैरेट केक पर बहुत गर्व है। यह नम और स्वादिष्ट है। कुछ रेसिपी की तरह गाजर का स्वाद दब जाने के बजाय, दालचीनी और वनीला से गाजर का स्वाद बहुत सुंदर ढंग से उभरता है। क्रीम चीज़ आइसिंग इस किडनी-अनुकूल कैरेट केक को पूर्ण बनाती है।","20","एक टुकड़ा 2-1/4\" x 2-1/8\"",
["2 कप मैदा (ऑल-पर्पज़ व्हाइट फ़्लोर)","1-3/4 कप दानेदार चीनी","1 कप खाना पकाने का तेल","4 बड़े अंडे","2 छोटे चम्मच बेकिंग सोडा","2 छोटे चम्मच दालचीनी","2 छोटे चम्मच वनीला (बँटा हुआ उपयोग)","2 बड़े चम्मच स्किम दूध","3 कप गाजर, कद्दूकस की हुई","8 औंस क्रीम चीज़","1/4 कप मक्खन","1 कप पाउडर चीनी"],
["ओवन को 350° F पर गरम करें।","9″ x 11″ के बेकिंग पैन में चिकनाई लगाएँ।","एक बड़े कटोरे में मैदा, चीनी, बेकिंग सोडा और दालचीनी मिलाएँ। तेल, अंडे, 1 छोटा चम्मच वनीला और स्किम दूध डालें; चिकना होने तक मिलाएँ। कद्दूकस की हुई गाजर मिलाएँ।","घोल को पैन में डालें और 45 से 60 मिनट तक पकने तक बेक करें।","केक को पूरी तरह ठंडा होने दें।","आइसिंग बनाने के लिए मक्खन, क्रीम चीज़, पाउडर चीनी और 1 छोटा चम्मच वनीला को चिकना होने तक फेंटें। ठंडे हुए कैरेट केक के ऊपर फैलाएँ।","काटें और परोसें।"],
["कन्फेक्शनर्स शुगर को पाउडर चीनी भी कहा जाता है।","पकने की जाँच के लिए केक में चाकू डालें। अगर वह सूखा बाहर आता है, तो केक तैयार है।","1 पाउंड बिना छँटी गाजर से लगभग 3 कप कद्दूकस की हुई गाजर मिलती है।"],
["1 स्टार्च","3-1/2 वसा","1 उच्च कैलोरी"]))
r.append(R(3903,"थाई पीनट करी ज़ूडल्स विद श्रिंप एंड बेक्ड टोफू","अलग-अलग साबुत खाद्य पदार्थों और शाकाहारी प्रोटीन को शामिल करने का यह एक बेहतरीन तरीका है।","4","1/4 कप ज़ूडल्स, 1/4 टोफू, 2 झींगे, 1/4 कप करी सॉस",
["14 औंस का डिब्बा सख़्त या एकदम सख़्त टोफू","1 बड़ा चम्मच + 1 छोटा चम्मच जैतून का तेल, बँटा हुआ","2 बड़े चम्मच कोकोनट एमिनोज़, बँटा हुआ","1 बड़ा चम्मच कॉर्न स्टार्च","1 कप तोरी (ज़ुकीनी)","1 बड़ा चम्मच थाई रेड करी","1/2 कप नारियल क्रीम","1/4 कप पीनट बटर","1 बड़ा चम्मच बिना दबाई ब्राउन शुगर","2 बड़े चम्मच सेब का सिरका","1/2 कप पानी","8-10 झींगे","1/2 नींबू (लाइम)","1/8 छोटा चम्मच काली मिर्च","2 लहसुन की कलियाँ","1/2 लाल शिमला मिर्च","सजावट के लिए धनिया, वैकल्पिक"],
["टोफू को तौलियों से दबाकर पानी निकालें/सोखें। ज़रूरत हो तो नए तौलियों के साथ दोहराएँ।","ओवन को 400 F पर पहले से गरम करें। टोफू को 1-इंच के टुकड़ों में काटें। एक मध्यम कटोरे में टोफू को तेल, 1 बड़ा चम्मच कोकोनट एमिनोज़ और कॉर्न स्टार्च के साथ उछालकर मिलाएँ। बेकिंग शीट पर 20-25 मिनट या किनारों के सुनहरे भूरे होने तक बेक करें।","इस बीच, स्पाइरल टूल या हाथ वाले स्पाइरलाइज़र से तोरी के नूडल्स बनाएँ। आप चाहें तो उन्हें सब्जी छीलने वाले पीलर से पतली पट्टियों में या टुकड़ों में भी काट सकते हैं।","एक मध्यम बर्तन में रेड करी, नारियल क्रीम, पीनट बटर, बचा हुआ कोकोनट एमिनोज़, ब्राउन शुगर, सेब का सिरका और पानी मिलाएँ। बीच-बीच में चलाते हुए लगभग 10 मिनट धीमी आँच पर पकाएँ।","झींगों को छीलें और उनकी नस निकाल दें, आधे नींबू का रस और काली मिर्च डालें। एक मध्यम नॉन-स्टिक पैन में झींगों को बचे हुए जैतून के तेल में हर तरफ़ 2-3 मिनट, उनके चटक गुलाबी होने तक भूनें। अलग रख दें।","लहसुन को बारीक काटें और शिमला मिर्च को पट्टियों में काटें। इन्हें तोरी के साथ मध्यम-तेज़ आँच पर वापस पैन में डालें और 3-4 मिनट पकाएँ। ज़्यादा न पकाएँ, नहीं तो ज़ूडल्स पानी छोड़ देंगे।","तोरी के नूडल्स को चार प्लेटों में रखें और हर प्लेट पर टोफू, झींगे और करी सॉस बराबर बाँटें। ऊपर से धनिया की पत्तियाँ डालें।"],
["कोकोनट एमिनोज़ की सबसे कम सोडियम वाली किस्म ढूँढें। कुछ में सोडियम सामान्य सोया सॉस जितना अधिक हो सकता है।","तोरी के नूडल्स की जगह सोबा नूडल्स इस्तेमाल किए जा सकते हैं। इससे लगभग 6 ग्राम कार्बोहाइड्रेट, 15 मिग्रा अधिक सोडियम और 70 मिग्रा कम पोटैशियम जुड़ेगा।","यह व्यंजन एक संपूर्ण भोजन है। नए शोध से हमें पता चला है कि टोफू, पीनट बटर और सब्जियों जैसे साबुत खाद्य स्रोतों से सारा पोटैशियम और फॉस्फोरस अवशोषित नहीं होता।"],
["2 प्रोटीन","1/2 सब्जी, कम पोटैशियम","3-1/2 वसा","2 उच्च कैलोरी"]))
r.append(R(3904,"घर का बना बीबीक्यू सॉस","इस स्वादिष्ट सॉस में प्रति सर्विंग केवल 51 मिग्रा सोडियम है, और इसे चिकन, बीफ़, बर्गर या किसी भी बीबीक्यू-आधारित रेसिपी में इस्तेमाल किया जा सकता है।","16","2 बड़े चम्मच",
["2 बड़े चम्मच कैनोला तेल","1/4 कप शहद","2 बड़े चम्मच ब्राउन शुगर","1/4 कप सेब का सिरका","2 बड़े चम्मच मीठा प्याज़","1 कप पानी","1 छोटी लहसुन की कली","2 छोटे चम्मच सूखी सरसों","2 बड़े चम्मच टमाटर पेस्ट","1 छोटा चम्मच Tabasco® तीखा मिर्च सॉस","1 छोटा चम्मच Kitchen Bouquet® ब्राउनिंग और सीज़निंग सॉस","1-1/2 बड़ा चम्मच मक्खन","1/4 छोटा चम्मच नमक"],
["प्याज़ कद्दूकस करें और लहसुन की कली को बारीक काटें।","सारी सामग्री को धीमी आँच पर तब तक गरम करें जब तक मक्खन पिघल न जाए और प्याज़ तथा लहसुन नरम होकर पक न जाएँ।","सॉस तुरंत इस्तेमाल के लिए तैयार है, या इसे ढके हुए डिब्बे में फ्रिज में एक सप्ताह तक रखा जा सकता है।"],
["गाढ़ा सॉस बनाने के लिए पकाते समय 1 बड़ा चम्मच मैदा या 1 छोटा चम्मच चावल का आटा डालें।","बाज़ार में बना बीबीक्यू सॉस औसतन 2 बड़े चम्मच की सर्विंग में 350 मिग्रा सोडियम देता है। इस रेसिपी में 1/4 छोटा चम्मच नमक सहित केवल 51 मिग्रा सोडियम है। अगर आप नमक न डालें, तो प्रति सर्विंग सोडियम केवल 18 मिग्रा है।"],
["1/2 उच्च कैलोरी"]))
r.append(R(3905,"बेसिल चिकन","बेसिल चिकन की इस ताज़ा, किडनी-अनुकूल रेसिपी को आज़माएँ।","4","1 चिकन ब्रेस्ट",
["4 बिना त्वचा के चिकन ब्रेस्ट","1/3 कप ट्रांस-फ़ैट रहित मार्जरीन","1/4 कप ताज़ी तुलसी","1 बड़ा चम्मच कद्दूकस किया हुआ परमेज़ान चीज़","1/4 छोटा चम्मच लहसुन पाउडर","1/4 छोटा चम्मच Mrs. Dash® हर्ब सीज़निंग मिश्रण","4 ताज़ी तुलसी की टहनियाँ, वैकल्पिक सजावट"],
["ओवन को 325° F पर पहले से गरम करें।","चिकन ब्रेस्ट के आधे टुकड़ों को काँच के बेकिंग पैन में रखें। हर ब्रेस्ट में काँटे से कई बार छेद करें ताकि पकते समय मिश्रण का मसाला और स्वाद अंदर तक पहुँचे।","काँच के मिक्सिंग बाउल में मार्जरीन को माइक्रोवेव में पिघलाएँ। 15 सेकंड से शुरू करें और गरमी बराबर फैलाने के लिए चलाएँ।","पिघले हुए मार्जरीन में तुलसी, परमेज़ान चीज़, लहसुन पाउडर और Mrs. Dash® डालें। मिश्रण को काँटे या फेंटनी से चलाएँ।","मिश्रण को चिकन ब्रेस्ट पर बराबर डालें और ध्यान रखें कि परमेज़ान चीज़ अच्छी तरह फैल जाए।","बिना ढके बेक करें, हर 10 मिनट में पैन के मिश्रण से बेस्ट करें, कुल लगभग 25 मिनट या जब तक चिकन का रस साफ़ न हो जाए, गुलाबी न रहे।"],
["अगर ताज़ी तुलसी उपलब्ध न हो, तो 2 बड़े चम्मच सूखी तुलसी इस्तेमाल की जा सकती है।","परमेज़ान चीज़ के एक बड़े चम्मच में 36 मिलीग्राम फॉस्फोरस होता है। मुख्य बात यह है कि फॉस्फोरस कम रखने के लिए रेसिपी में इसकी बहुत थोड़ी मात्रा ही रखें।","इस रेसिपी का उपयोग बिना डायलिसिस वाले CKD आहार में किया जा सकता है, लेकिन कम प्रोटीन वाले आहार के लिए मात्रा समायोजित करनी पड़ सकती है। अपनी व्यक्तिगत प्रोटीन ज़रूरतों के अनुसार बदलावों के बारे में अपने आहार विशेषज्ञ से पूछें।"],
["3-1/2 मांस","1/2 वसा"]))
r.append(R(3906,"एशियन ऑरेंज चिकन","खट्टे फल, अदरक, लहसुन, राइस विनेगर, कम सोडियम वाला सोया सॉस और लाल मिर्च के गुच्छे मिलकर इस स्वादिष्ट एशियन ऑरेंज चिकन के लिए मैरिनेड और सॉस बनाते हैं।","4","रेसिपी का 1/4 हिस्सा",
["1-3/4 कप पानी","2 बड़े चम्मच संतरे का रस","1/4 कप नींबू का रस","1/3 कप बिना मसाले वाला राइस विनेगर","2 बड़े चम्मच कम सोडियम वाला सोया सॉस","1 बड़ा चम्मच संतरे का ज़ेस्ट (छिलका)","1/3 कप दबाकर भरी हुई ब्राउन शुगर","1/2 छोटा चम्मच ताज़ा अदरक","1 लहसुन की कली","2 बड़े चम्मच हरा प्याज़","1/4 छोटा चम्मच लाल मिर्च के गुच्छे","1/2 पाउंड बिना हड्डी और बिना त्वचा वाले चिकन ब्रेस्ट","2-1/2 बड़े चम्मच कॉर्नस्टार्च","3 बड़े चम्मच जैतून का तेल"],
["अदरक और लहसुन को बारीक काटें। हरा प्याज़ काटें।","1-1/2 कप पानी, संतरे का रस, नींबू का रस, राइस विनेगर और सोया सॉस को सॉसपैन में डालें और मध्यम-तेज़ आँच पर रखें। संतरे का ज़ेस्ट, ब्राउन शुगर, अदरक, लहसुन, कटा प्याज़ और लाल मिर्च के गुच्छे डालकर चलाएँ। उबाल आने दें। आँच से उतारें और 10 से 15 मिनट ठंडा होने दें।","चिकन को 1/2-इंच के टुकड़ों में काटें और दोबारा बंद होने वाले प्लास्टिक बैग में रखें। जब सॉसपैन की सामग्री ठंडी हो जाए, तो 1 कप सॉस बैग में डालें। बचा हुआ सॉस अलग रख लें। बैग को बंद करें और कम से कम 2 घंटे फ्रिज में रखें।","एक बड़ी कड़ाही में जैतून का तेल मध्यम आँच पर गरम करें। मैरिनेट किए हुए चिकन को कड़ाही में रखें और दोनों तरफ़ से भूरा करें। पेपर टॉवल बिछी प्लेट पर निथारें और अलग रख दें।","कड़ाही को पोंछ दें और सॉस डालें। मध्यम-तेज़ आँच पर उबाल आने दें। कॉर्नस्टार्च और बचा हुआ 1/4 कप पानी मिलाएँ; इसे सॉस में चलाकर डालें। आँच मध्यम-धीमी करें, चिकन के टुकड़े डालें और बीच-बीच में चलाते हुए लगभग 5 मिनट धीमी आँच पर पकाएँ।","4 हिस्सों में बाँटें और गरमागरम परोसें।"],
["भोजन पूरा करने के लिए भाप में पके चावल के साथ परोसें।","चिकन ब्रेस्ट की जगह टर्की कटलेट या चिकन जाँघ का मांस इस्तेमाल किया जा सकता है।","ध्यान दें कि पानी चरण 2 और 5 में उपयोग के लिए बँटा हुआ है। सॉस भी मैरिनेट करने और अंतिम सॉस बनाने के लिए बँटा हुआ है।"],
["2 मांस","1/2 फल, कम पोटैशियम","1 वसा","1/2 उच्च कैलोरी"]))
r.append(R(3910,"प्रोटीन बूस्टर ब्लूबेरी मफ़िन","ग्रीक योगर्ट और व्हे प्रोटीन पाउडर प्रोटीन बूस्टर ब्लूबेरी मफ़िन को 10 ग्राम उच्च गुणवत्ता वाला प्रोटीन देते हैं।","12","1 मफ़िन",
["1 कप रोल्ड ओट्स","1 कप सादा वसा-रहित ग्रीक योगर्ट","1/2 कप जैतून का तेल","1/4 कप पानी","3/4 कप ब्राउन शुगर","1 बड़ा अंडा","1 कप मैदा (ऑल-पर्पज़ फ़्लोर)","1-1/3 कप व्हे प्रोटीन पाउडर","1/2 छोटा चम्मच नमक","1/2 छोटा चम्मच बेकिंग सोडा","1/2 छोटा चम्मच क्रीम ऑफ़ टार्टर","1 कप ताज़ी ब्लूबेरी"],
["ओवन को 350° F पर पहले से गरम करें।","एक बड़े कटोरे में ओट्स को योगर्ट के साथ मिलाएँ। तेल, पानी, चीनी और अंडा डालकर अच्छी तरह मिलाएँ।","एक अलग कटोरे में मैदा, प्रोटीन पाउडर, नमक, बेकिंग सोडा और क्रीम ऑफ़ टार्टर मिलाएँ।","सूखी सामग्री को गीली सामग्री में मिलाएँ। ब्लूबेरी डालें और अच्छी तरह मिलाएँ।","12 मफ़िन कप भरें या मफ़िन पैन में चिकनाई लगाएँ और घोल से उन्हें 2/3 भरें। 20 से 25 मिनट या छूने पर कड़क होने तक बेक करें।"],
["जब ताज़ी ब्लूबेरी का मौसम न हो, तो जमी हुई ब्लूबेरी का उपयोग करें।","उच्च प्रोटीन वाले क्रैनबेरी मफ़िन बनाने के लिए ब्लूबेरी की जगह क्रैनबेरी इस्तेमाल करें।"],
["1 मांस","1 स्टार्च","1 वसा","1 उच्च कैलोरी"]))
r.append(R(3912,"सैल्मन स्टेक्स विद हर्ब ड्रेसिंग","वॉशिंगटन की DaVita आहार विशेषज्ञ ब्रेंडा की सैल्मन स्टेक्स विद हर्ब ड्रेसिंग की इस स्वादिष्ट किडनी-अनुकूल रेसिपी को आज़माएँ।","6","3-1/2 औंस सैल्मन स्टेक और 2-1/2 बड़े चम्मच ड्रेसिंग",
["3/4 कप मेयोनेज़","3 बड़े चम्मच छाछ (बटरमिल्क)","3 बड़े चम्मच ताज़ी सोया (डिल वीड)","1 बड़ा चम्मच ताज़े चाइव्स","2 नींबू","1 मध्यम प्याज़","10 साबुत काली मिर्च के दाने","3 अजमोद (पार्सले) की टहनियाँ","2 तेज पत्ते","1/2 छोटा चम्मच नमक","2 पाउंड सैल्मन स्टेक"],
["एक नींबू को 6 फाँकों में काटें और अलग रख दें। दूसरे नींबू के छिलके से 1/2 छोटा चम्मच ज़ेस्ट निकालें। नींबू का रस निकालें, जिससे 5 बड़े चम्मच बनेगा। प्याज़ के स्लाइस काटें और अजमोद तथा सोया को काटें।","ड्रेसिंग के लिए, एक छोटे मिक्सिंग बाउल में मेयोनेज़ या सलाद ड्रेसिंग, छाछ, 2 बड़े चम्मच सोया, चाइव्स, नींबू का ज़ेस्ट और 1 बड़ा चम्मच नींबू का रस मिलाएँ। ढककर कम से कम एक घंटा ठंडा करें।","12″ की कड़ाही में 1-1/2 कप पानी, बचा हुआ 4 बड़े चम्मच नींबू का रस, प्याज़, काली मिर्च के दाने, अजमोद, तेज पत्ते और नमक मिलाएँ। उबाल आने दें; सैल्मन स्टेक्स डालें। ढक दें; 8 से 12 मिनट (जमी हुई के लिए 12 से 18 मिनट) या मछली के काँटे से जाँचने पर बस आसानी से टूटने तक धीमी आँच पर पकाएँ।","सैल्मन स्टेक्स को ऊपर से ड्रेसिंग डालकर परोसें। बची हुई सोया और नींबू की फाँकों से सजाएँ।"],
["आपको 1 से 1-1/4″ मोटे कटे 6 सैल्मन स्टेक चाहिए होंगे (लगभग 2 पाउंड)।","कम प्रोटीन वाले आहार के लिए, सर्विंग घटाकर 1/2 सैल्मन फ़िले, पकाने के बाद लगभग 1-3/4 से 2 औंस, कर दें।","प्रति सर्विंग वसा को 8 ग्राम तक घटाने के लिए वसा-रहित मेयोनेज़ का उपयोग करें।"],
["4 मांस","3 वसा"]))
